class DetectSquares {
    private java.util.Map<String, Integer> counts;
    private java.util.List<int[]> points;

    public DetectSquares() {
        counts = new java.util.HashMap<>();
        points = new java.util.ArrayList<>();
    }

    public void add(int[] point) {
        String key = point[0] + "," + point[1];
        counts.merge(key, 1, Integer::sum);
        points.add(point);
    }

    public int count(int[] point) {
        int px = point[0], py = point[1], result = 0;
        for (int[] p : points) {
            int x = p[0], y = p[1];
            if (Math.abs(px - x) != Math.abs(py - y) || px == x && py == y) continue;
            result += counts.getOrDefault(px + "," + y, 0)
                    * counts.getOrDefault(x + "," + py, 0);
        }
        return result;
    }
}

import java.util.*;

class DetectSquares {
    private int[][] grid;
    private List<int[]> pointsList;

    public DetectSquares() {
        grid = new int[1001][1001];
        pointsList = new ArrayList<>();
    }

    public void add(int[] point) {
        grid[point[0]][point[1]]++;
        pointsList.add(point);
    }

    public int count(int[] point) {
        int px = point[0], py = point[1];
        int result = 0;
        for (int[] p : pointsList) {
            int x = p[0], y = p[1];
            int side = Math.abs(py - y);
            if (side == 0 || Math.abs(px - x) != side) continue;
            result += grid[px][y] * grid[x][py];
        }
        return result;
    }
}
